#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;
int main(){int n,m;cin>>n>>m;vector<vector<int>>g(n+1);vector<int>d(n+1);for(int i=0;i<m;++i){int u,v;cin>>u>>v;g[u].push_back(v);++d[v];}priority_queue<int,vector<int>,greater<int>>q;for(int i=1;i<=n;++i)if(!d[i])q.push(i);vector<int>a;while(!q.empty()){int u=q.top();q.pop();a.push_back(u);for(int v:g[u])if(--d[v]==0)q.push(v);}if((int)a.size()!=n){cout<<"IMPOSSIBLE\n";return 0;}for(int i=0;i<n;++i)cout<<(i?" ":"")<<a[i];cout<<'\n';}
